mapper.select:
SELECT * FROM ( SELECT B.BOARD_NO AS boardNo, B.BOARD_TITLE AS boardTitle, B.BOARD_CONTENT AS boardContent, B.BOARD_CATEGORY AS boardCategory, C.CATEGORY_NAME AS categoryName,
B.REF_MNO AS boardAuthor, M.MEMBER_ID AS memberId, M.MEMBER_IMAGE AS memberImage,
A.ATTACHMENT_PATH AS attachmentPath,
R.REGION_NO AS regionNo, R.REGION_NAME AS regionName,
B.REG_DATE AS regDate,
ROW_NUMBER() OVER (ORDER BY B.BOARD_NO DESC) AS RN FROM TB_BOARD B JOIN TB_MEMBER M ON B.REF_MNO = M.MEMBER_NO JOIN TB_CATEGORY C ON B.BOARD_CATEGORY = C.CATEGORY_NO LEFT JOIN TB_REGION R ON M.REF_RNO = R.REGION_NO LEFT JOIN ( -- 게시글별 대표 첨부파일 1개 (여기선 STATUS = 'Y' 중 첫 번째) SELECT REF_BNO, MIN(ATTACHMENT_PATH) AS ATTACHMENT_PATH FROM TB_ATTACHMENT WHERE STATUS = 'Y' GROUP BY REF_BNO ) A ON A.REF_BNO = B.BOARD_NO WHERE B.STATUS = 'Y' AND B.BOARD_CATEGORY LIKE #{category}
AND B.BOARD_NO < #{fetchOffset}
) WHERE RN <= #{limit}
